B.a_I=s(["\ubcf8\uc778\uc740 \ubcf8 \ub3d9\uc758\uc11c\uc758 \uc804\uccb4 \ub0b4\uc6a9\uc744 \uc77d\uace0 \uc774\ud574\ud558\uc600\uc73c\uba70, \uad81\uae08\ud55c \uc0ac\ud56d\uc5d0 \ub300\ud574 \uc124\uba85\uc744 \uc694\uccad\ud560 \uae30\ud68c\ub97c \uac00\uc84c\uc2b5\ub2c8\ub2e4.","\ubcf8\uc778\uc740 \uac15\uc694 \uc5c6\uc774 \uc790\ubc1c\uc801\uc778 \uc758\uc0ac\ub85c \ubcf8 \ub3d9\uc758\uc11c\uc5d0 \uc11c\uba85\ud569\ub2c8\ub2e4."],t.s)
B.aoD=new A.ee("\uc81c9\uc870. \ucd5c\uc885 \ud655\uc778",B.a_I,B.B)
B.a1q=s([B.aop,B.aou,B.aoz,B.aom,B.aoj,B.aoy,B.aot,B.aoD],t.H9)
