B.aod=new A.hn("health","\uac74\uac15 \uc0c1\ud0dc\ub97c \uc815\ud655\ud788 \uace0\uc9c0\ud558\uace0 \uc758\ud559 \uc9c4\uc220\uc11c\xb7\ud544\uc694 \uc2dc \uc758\ub8cc\ud655\uc778\uc5d0 \uc751\ud558\uaca0\uc2b5\ub2c8\ub2e4.")
B.ao7=new A.hn("rules","\uac15\uc0ac \uc9c0\uc2dc\xb7\uc548\uc804\uc218\uce59\xb7\ubc84\ub514 \uc2dc\uc2a4\ud15c\xb7\ube44\uc0c1\uc808\ucc28\ub97c \uc900\uc218\ud569\ub2c8\ub2e4.")
B.rD=new A.hn("apdi","APDI\uc640 \uad50\uc721\uae30\uad00\xb7\uac15\uc0ac\uc758 \uad00\uacc4\uac00 \ub3c5\ub9bd\uc801\uc77c \uc218 \uc788\uc74c\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.")
